                           //     （`null` = 渲染「—」且**不计入**当日合计；把上一期那个 −213.45 再记一遍＝重复计入 ✗、用 0 冒充 ✗）
                           //   · ✅ **023402 广发精选的赎回已落地**（2026-10-21 补记）：10-19 确认、10-21 回款 20,913.44 到账
                           //     → 已从 funds **移除**（见数组内那段说明）＋ 进 OTC_CLEARED ＋ 进 data.js 的 CLOSED_GF ✓
