/* ---- 快照对比日志（MANUAL：每次发持仓截图解析后追加一份；页面自动 diff 相邻两份） ----
 * 两种形态（v6.9）：
 *   完整快照：{ d, cash, pl?, day?, tag?, note?, items: { code: { name, qty, cost, val, pl } } } —— 发截图解析后追加
 *   简快照（历史补录，无持仓明细）：{ d, total, pl, day?, tag?, note? }
 * 口径：total = 总资产（Σ市值 + 现金，简快照直接记 App 读数）；pl = 持仓累计浮盈亏（App 读数，不含现金）
 *       item 的 cost = val − pl（App 市值/盈亏是精确值，成本是推导值）
 *       day = 当日盈亏（App「当日」读数，仅展示用；未更新的基金不参与求和，覆盖范围见 note，勿用于归因）
 * 累计投入（走势图虚线）= 总资产 − 累计浮盈亏（现金项自然抵消，= 持仓成本 + 现金）
 * 资金归因（恒等式，无假设）：Δ总资产 = Δ浮盈亏 + 外部资金进出（= Δ累计投入）。
 *   场内/场外加仓是「现金→持仓」的内部转换，不改变总资产也不计入资金进出；只有外部转入/转出才计。
 *   flow 字段仅在人工确知转入/转出金额时记录（覆盖推导值）；未记录时页面按 Δ累计投入自动推导
 *   （含场外自动定投与 App 口径微调，如 09-07 定投 200 在途）。⚠ 勿用「当日盈亏」冒充期间市值变化——
 *   09-01/02 的下跌会被漏计（v6.8 曾因此把 09-03 外部转入 25,243 低估为实际约 32,073）。
 * tag = 事件标签（加仓/减仓/清仓）；note = 该期解读（自动显示在 diff 卡片底部 ▸ 行） */
